from azure.ai.documentintelligence import DocumentIntelligenceClient
from azure.ai.documentintelligence.models import AnalyzeDocumentRequest
from azure.core.credentials import AzureKeyCredential

def validate_document_fields(payload, config=None):
    config = config or {}
    endpoint = os.environ["DOCUMENTINTELLIGENCE_ENDPOINT"]
    key = os.environ["DOCUMENTINTELLIGENCE_API_KEY"]

    document_intelligence_client = DocumentIntelligenceClient(
        endpoint=endpoint, credential=AzureKeyCredential(key)
    )

    poller = document_intelligence_client.begin_analyze_document(
        # Using a prebuilt model for invoices as an example
        "prebuilt-invoice", AnalyzeDocumentRequest(url_source=payload)
    )
    analyze_result = poller.result()

    if not analyze_result.documents:
        validation_output = {
            "is_valid": False,
            "errors": ["No document could be analyzed from the payload."],
            "extracted_fields": {},
        }
    else:
        # Assuming we process the first document found
        doc = analyze_result.documents[0]

        extracted_fields = {}
        for name, field in doc.fields.items():
            field_value = (
                field.get("value") if field and field.get("value") is not None else field.get("content")
            )
            extracted_fields[name] = {
                "value": field_value,
                "confidence": field.get("confidence") if field else None,
            }

        errors = []
        required_fields = config.get("required_fields", [])
        min_confidence_thresholds = config.get("min_confidence", {})

        for field_name in required_fields:
            field_data = extracted_fields.get(field_name)
            if not field_data or field_data.get("value") is None:
                errors.append(f"Required field '{field_name}' is missing or has no value.")
                continue  # Skip confidence check if field is missing

            if field_name in min_confidence_thresholds:
                confidence = field_data.get("confidence")
                threshold = min_confidence_thresholds[field_name]
                if confidence is None:
                    errors.append(f"Confidence score for '{field_name}' is not available.")
                elif confidence < threshold:
                    errors.append(
                        f"Field '{field_name}' confidence {confidence:.2f} is below threshold {threshold:.2f}."
                    )

        validation_output = {
            "is_valid": not errors,
            "errors": errors,
            "extracted_fields": extracted_fields,
        }
    result = validation_output
    return result
